def get(url,params,post=False):
    encoded=urlencode(params)
    full=url if post else url+'?'+encoded
    with urlopen(Request(full,data=encoded.encode() if post else None,headers={'User-Agent':'Mozilla/5.0 utility-data-collection'}),timeout=180) as r: data=r.read()
    value=json.loads(data)
    if 'error' in value: raise RuntimeError(str(value['error']))
    return data,value
def layer(name,url):
    folder=ROOT/name; folder.mkdir(parents=True,exist_ok=True)
    # Never leave an old success marker beside a partially refreshed snapshot.
    (folder/'snapshot.json').unlink(missing_ok=True)
    raw,meta=get(url,{'f':'json'}); (folder/'layer_metadata.json').write_bytes(raw)
    _,counts=get(url+'/query',{'where':'1=1','returnCountOnly':'true','f':'json'})
    _,iddata=get(url+'/query',{'where':'1=1','returnIdsOnly':'true','f':'json'})
    ids=sorted(iddata['objectIds']); field=meta.get('objectIdField') or iddata.get('objectIdFieldName') or next(f['name'] for f in meta['fields'] if f['type']=='esriFieldTypeOID'); page_size=min(25 if name in {'new_hampshire_water_service_areas_des','connecticut_community_water_service_areas_dph','virginia_state_sewer_area_vdh_deq_2019'} else 1000,meta['maxRecordCount'])
    def page(start,size):
        subset=ids[start:start+size]
        params={'objectIds':','.join(map(str,subset)),'outFields':'*','returnGeometry':'true','returnZ':str(bool(meta.get('hasZ'))).lower(),'returnM':str(bool(meta.get('hasM'))).lower(),'f':'json'}
        raw,obj=get(url+'/query',params,post=True)
        def object_id(feature):
            attributes=feature['attributes']
            if field in attributes: return attributes[field]
            matching=[v for k,v in attributes.items() if k.casefold()==field.casefold()]
            if len(matching)!=1: raise ValueError('Cannot uniquely identify object ID field '+field)
            return matching[0]
        received=[object_id(f) for f in obj['features']]
        if set(received)!=set(subset) or obj.get('exceededTransferLimit'): raise ValueError('Missing or truncated IDs at '+str(start))
        path=folder/('page_%06d.json.gz'%start)
        with gzip.open(path,'wb') as f: f.write(raw)
        return {'file':path.name,'features':len(received),'sha256':hashlib.sha256(path.read_bytes()).hexdigest()}
    pages=[]
    # The Connecticut service times out on the first 25 polygons as one batch.
    # Request them individually; use the usual 25-feature batches thereafter.
    if name=='connecticut_community_water_service_areas_dph':
        batches=[(i,1) for i in range(min(25,len(ids)))] + [(i,page_size) for i in range(25,len(ids),page_size)]
    else:
        batches=[(i,page_size) for i in range(0,len(ids),page_size)]
    with ThreadPoolExecutor(max_workers=4) as pool:
        for future in as_completed([pool.submit(page,i,size) for i,size in batches]):
            p=future.result(); pages.append(p); print(name,p['file'],p['features'],flush=True)
    summary={'source_layer':url,'retrieved_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'requested_z':bool(meta.get('hasZ')),'requested_m':bool(meta.get('hasM')),'expected_count_at_start':counts['count'],'id_count':len(ids),'downloaded_count':sum(p['features'] for p in pages),'pages':sorted(pages,key=lambda p:p['file'])}
    if counts['count'] != len(ids) or len(ids)!=summary['downloaded_count']: raise ValueError('feature count mismatch')
    (folder/'snapshot.json').write_text(json.dumps(summary,indent=2),encoding='utf-8')
if __name__=='__main__':
    import sys
    for name,url in LAYERS.items():
        if len(sys.argv)>1 and name not in sys.argv[1:]: continue
        try: layer(name,url)
        except Exception as e: print('FAILED',name,str(e),flush=True)
